"use client";

import { useState } from "react";
import { 
  MapPin, Phone, Mail, Clock, Calendar, 
  Send, MessageCircle, Instagram, Facebook, Globe, Search 
} from "lucide-react";

export default function ContactPage() {
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    phone: "",
    service: "",
    preferredDate: "",
    preferredTime: "",
    message: ""
  });

  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState("");
  const [error, setError] = useState("");

  const services = [
    "Tarot Reading",
    "Numerology Consultation", 
    "Angel Healing",
    "Vastu Consultation",
    "Astrology Reading",
    "Spells"
  ];

  const timeSlots = [
    "10:00 AM", "11:00 AM", "12:00 PM", 
    "2:00 PM", "3:00 PM", "4:00 PM", 
    "5:00 PM", "6:00 PM"
  ];

  const handleSubmit = async (e) => {
    e.preventDefault();

    // ✅ Validation
    if (!formData.name || !formData.email || !formData.phone || !formData.service) {
      setError("Please fill in all required fields: Name, Email, Phone, and Service.");
      return;
    }
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(formData.email)) {
      setError("Please enter a valid email address.");
      return;
    }
    const phoneRegex = /^[0-9]{10}$/;
    if (!phoneRegex.test(formData.phone.replace(/\D/g, ""))) {
      setError("Please enter a valid 10-digit phone number.");
      return;
    }

    setLoading(true);
    setError("");
    setSuccess("");

    try {
      const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/appointments`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          fullName: formData.name,
          email: formData.email,
          phone: formData.phone,
          service: formData.service,
          date: formData.preferredDate,
          time: formData.preferredTime,
          message: formData.message
        })
      });

      if (!res.ok) throw new Error("Failed to book appointment");

      setSuccess("✅ Appointment booked successfully! We will contact you soon.");
      setFormData({
        name: "",
        email: "",
        phone: "",
        service: "",
        preferredDate: "",
        preferredTime: "",
        message: ""
      });
    } catch (err) {
      setError("❌ Something went wrong. Please try again later.");
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (field, value) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
  };

  return (
    <div
      className="relative min-h-screen py-10 text-[#FFD700] overflow-hidden bg-cover bg-center"
      style={{ backgroundImage: "url('/assets/bg.png')" }}
    >
      <div className="relative container mx-auto px-4">
        {/* Header */}
        <section className="text-center mb-16 relative z-10">
          <h1 className="text-5xl font-bold mb-6 bg-gradient-to-r from-yellow-300 via-yellow-400 to-orange-400 text-transparent bg-clip-text">
            Book Your Session
          </h1>
          <p className="text-xl text-yellow-100/90 max-w-3xl mx-auto">
            Take the first step on your spiritual journey. Schedule a consultation 
            and discover the divine guidance that awaits you.
          </p>
        </section>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 relative z-10">
          {/* Contact Form */}
          <div className="bg-[#3b0022] text-[rgb(255,237,137)] rounded-2xl shadow-lg p-6 border border-yellow-100/20">
            <h2 className="text-2xl font-semibold flex items-center mb-6">
              <Calendar className="h-6 w-6 mr-2 text-yellow-200" />
              Schedule Appointment
            </h2>

            {success && <p className="text-green-400 mb-4">{success}</p>}
            {error && <p className="text-red-400 mb-4">{error}</p>}

            <form onSubmit={handleSubmit} className="space-y-6">
              {/* Name + Email */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <input
                  type="text"
                  placeholder="Full Name *"
                  value={formData.name}
                  onChange={(e) => handleInputChange("name", e.target.value)}
                  className="w-full border border-yellow-100/20 bg-[#3b0022] rounded-md p-2 text-yellow-200"
                />
                <input
                  type="email"
                  placeholder="Email Address *"
                  value={formData.email}
                  onChange={(e) => handleInputChange("email", e.target.value)}
                  className="w-full border border-yellow-100/20 bg-[#3b0022] rounded-md p-2 text-yellow-200"
                />
              </div>

              {/* Phone */}
              <input
                type="tel"
                placeholder="Phone Number *"
                value={formData.phone}
                onChange={(e) => handleInputChange("phone", e.target.value)}
                className="w-full border border-yellow-100/20 bg-[#3b0022] rounded-md p-2 text-yellow-200"
              />

              {/* Service */}
              <select
                value={formData.service}
                onChange={(e) => handleInputChange("service", e.target.value)}
                className="w-full border border-yellow-100/20 bg-[#3b0022] rounded-md p-2 text-yellow-200"
              >
                <option value="">Select a service *</option>
                {services.map((service) => (
                  <option key={service} value={service}>{service}</option>
                ))}
              </select>

              {/* Date + Time */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <input
                  type="date"
                  value={formData.preferredDate}
                  onChange={(e) => handleInputChange("preferredDate", e.target.value)}
                  min={new Date().toISOString().split("T")[0]}
                  className="w-full border border-yellow-100/20 bg-[#3b0022] rounded-md p-2 text-yellow-200"
                />
                <select
                  value={formData.preferredTime}
                  onChange={(e) => handleInputChange("preferredTime", e.target.value)}
                  className="w-full border border-yellow-100/20 bg-[#3b0022] rounded-md p-2 text-yellow-200"
                >
                  <option value="">Select time</option>
                  {timeSlots.map((time) => (
                    <option key={time} value={time}>{time}</option>
                  ))}
                </select>
              </div>

              {/* Message */}
              <textarea
                placeholder="Additional Message (optional)"
                value={formData.message}
                onChange={(e) => handleInputChange("message", e.target.value)}
                className="w-full border border-yellow-100/20 bg-[#3b0022] rounded-md p-2 min-h-[100px] text-yellow-200"
              />

              {/* Submit */}
              <button
                type="submit"
                disabled={loading}
                className="w-full flex items-center justify-center gap-2 bg-[#FFD700] text-[#2a0015] font-bold py-3 px-6 rounded-xl hover:-translate-y-1 hover:bg-[#FFE066] transition-transform duration-300"
              >
                <Send className="inline h-4 w-4 mr-2" />
                {loading ? "Booking..." : "Send Appointment Request"}
              </button>
            </form>
          </div>

          {/* Right side (Contact Info, Socials, Expectations) */}
          {/* You can keep your existing code unchanged here */}
        </div>
      </div>
    </div>
  );
}
